from contextlib import closing
from datetime import datetime, timezone

import jwt as pyjwt
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from pydantic import BaseModel

from . import db, tokens
from .tokens import Clock, get_clock

app = FastAPI(title="auth-service")

bearer_scheme = HTTPBearer(auto_error=False)


class LoginRequest(BaseModel):
    username: str
    password: str


class RefreshRequest(BaseModel):
    refresh_token: str


class TokenPair(BaseModel):
    access_token: str
    refresh_token: str
    token_type: str = "bearer"
    expires_in: int = tokens.ACCESS_TTL_SECONDS


def _issue_pair(user_id: int, clock: Clock) -> TokenPair:
    now = clock()
    access = tokens.create_access_token(user_id, now)
    refresh = tokens.new_refresh_token()
    with closing(db.connect()) as conn:
        tokens.store_refresh_token(conn, user_id, refresh, now)
    return TokenPair(access_token=access, refresh_token=refresh)


@app.on_event("startup")
def _startup() -> None:
    db.init_db()
    db.seed_users({"alice": "wonderland", "bob": "builder"})


# --- POST /auth/login --------------------------------------------------------


@app.post("/auth/login", response_model=TokenPair)
def login(body: LoginRequest, clock: Clock = Depends(get_clock)):
    user = db.get_user_by_username(body.username)
    # Constant-shape failure: same error whether the user or password is wrong.
    if user is None or not db.verify_password(body.password, user["password_hash"]):
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, detail="invalid credentials")
    return _issue_pair(user["id"], clock)


# --- POST /auth/refresh ------------------------------------------------------


@app.post("/auth/refresh", response_model=TokenPair)
def refresh(body: RefreshRequest, clock: Clock = Depends(get_clock)):
    user_id = tokens.consume_refresh_token(body.refresh_token, clock)
    if user_id is None:
        raise HTTPException(
            status.HTTP_401_UNAUTHORIZED,
            detail="invalid or replayed refresh token",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return _issue_pair(user_id, clock)


# --- GET /me -----------------------------------------------------------------


def get_current_user(
    credentials: HTTPAuthorizationCredentials | None = Depends(bearer_scheme),
    clock: Clock = Depends(get_clock),
):
    if credentials is None:
        raise HTTPException(
            status.HTTP_401_UNAUTHORIZED,
            detail="missing bearer token",
            headers={"WWW-Authenticate": "Bearer"},
        )
    try:
        user_id = tokens.decode_access_token(credentials.credentials, clock)
    except pyjwt.ExpiredSignatureError:
        raise HTTPException(
            status.HTTP_401_UNAUTHORIZED,
            detail="access token expired",
            headers={"WWW-Authenticate": "Bearer"},
        )
    except pyjwt.InvalidTokenError:
        raise HTTPException(
            status.HTTP_401_UNAUTHORIZED,
            detail="invalid access token",
            headers={"WWW-Authenticate": "Bearer"},
        )
    user = db.get_user_by_id(user_id)
    if user is None:
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, detail="unknown user")
    return user


@app.get("/me")
def me(user=Depends(get_current_user), clock: Clock = Depends(get_clock)):
    return {
        "id": user["id"],
        "username": user["username"],
        "authenticated_at": datetime.fromtimestamp(clock(), tz=timezone.utc).isoformat(),
    }
"})
